comment-implementation.facts:
stored에는 siteId와 content가 있다. 다음은 draft.ts 전체다.
```ts
type Draft = { siteId: string; title: string };
declare function load(siteId: string): Promise<{ siteId: string; content: unknown } | null>;
declare function validate(value: Record<string, unknown>): Draft | null;
declare function saveSession(token: string): void;
declare const drafts: Draft[];

/** 저장된 내용이 요청한 사이트의 것인지 확인하고 현재 계약을 통과한 내용만 반환한다. */
export async function readDraft(siteId: string): Promise<Draft | null> {
  const stored = await load(siteId);
  if (stored === null || stored.siteId !== siteId) return null;
  const value = stored.content;
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return null;
  return validate(value as Record<string, unknown>);
}

/** 막혔다고 답한 뒤에도 연결이 열릴 수 있다. 닫지 않으면 다음 갱신을 계속 막는다. */
export function rememberSession(token: string): void {
  saveSession(token);
}

export function findDraft(siteId: string): Draft | undefined {
  return drafts[0];
}

// 외부 연동사는 requestId가 다른 승인 요청을 별도로 과금하므로 재시도에도 최초 requestId를 유지한다.
export function approvalRequest(requestId: string): { requestId: string } {
  return { requestId };
}
```
외부 연동사의 중복 과금 규칙은 계약서로 확인된 프로젝트 제약이다. 이번 태스크에서 그 함수의 동작을 바꾸지 않는다.

